command:
let nodes = select id, kind, file, span from "syntax-tree" where text = "" and glob_any(file, "crates/execution/src/**");
let paths = select * from nodes where kind = "path";
let visibility = select * from nodes where kind = "visibility";
let nested = axis(from=visibility, relation="syntax-child", direction=descendant, domain=paths);
let restricted = select r.file as source, r.span as span from nested as l join paths as r on l.related = r.id;
let declared = select source, target, written, span from "source-dependency" where glob_any(source, "crates/execution/src/**");
let dependencies = antijoin(left=declared, right=restricted, left-on=["source","span"], right-on=["source","span"]);
emit dependencies subject source key(source,target,written,span);
